15	// Pi JSONL entry types
16	const entryTypeMessage = "message"
17	
18	// maxScannerLine is 1 MB — large enough for Pi JSONL lines that may
19	// contain thinking blocks or full file contents in tool call arguments.
20	const maxScannerLine = 1 << 20
21	
22	func newJSONLScanner(data []byte) *bufio.Scanner {
23		s := bufio.NewScanner(bytes.NewReader(data))
24		s.Buffer(make([]byte, 0, maxScannerLine), maxScannerLine)
25		return s
26	}
27	
28	// countLines returns the number of non-empty lines in data.
29	func countLines(data []byte) int {
30		if len(data) == 0 {
31			return 0
32		}
33		n := bytes.Count(data, []byte{'\n'})
34		// Count final line if it doesn't end with newline
35		if len(data) > 0 && data[len(data)-1] != '\n' {
36			n++
37		}
38		return n
39	}
40	
41	// skipLines returns data with the first n lines removed.
42	func skipLines(data []byte, n int) []byte {
43		if n <= 0 {
44			return data
45		}
46		off := 0
47		for i := 0; i < n && off < len(data); i++ {
48			idx := bytes.IndexByte(data[off:], '\n')
49			if idx < 0 {
50				return nil // fewer lines than offset
51			}
52			off += idx + 1
53		}
54		return data[off:]
55	}
