98	// resolveActiveBranch parses JSONL data and returns the set of entry IDs on
99	// the active conversation branch. Pi transcripts form a tree (entries have id
100	// and parentId); the active branch is the path from the root to the last
101	// message entry in the file.
102	// Returns nil if the transcript has no tree structure or cannot be resolved.
103	func resolveActiveBranch(data []byte) map[string]bool {
104		type node struct {
105			Type     string  `json:"type"`
106			ID       string  `json:"id"`
107			ParentID *string `json:"parentId"`
108		}
109	
110		var lastMessageID string
111		hasTree := false
112		parentOf := make(map[string]string)
113	
114		scanner := newJSONLScanner(data)
115		for scanner.Scan() {
116			var n node
117			if err := json.Unmarshal(scanner.Bytes(), &n); err != nil || n.ID == "" {
118				continue
119			}
120			if n.ParentID != nil {
121				parentOf[n.ID] = *n.ParentID
122				if *n.ParentID != "" {
123					hasTree = true
124				}
125			}
126			if n.Type == entryTypeMessage {
127				lastMessageID = n.ID
128			}
129		}
130	
131		// No tree references — all entries are on the active branch.
132		if !hasTree || lastMessageID == "" {
133			return nil
134		}
135	
136		active := make(map[string]bool)
137		for cur := lastMessageID; cur != ""; {
138			if active[cur] {
139				break // cycle protection
140			}
141			active[cur] = true
142			parent, ok := parentOf[cur]
143			if !ok {
144				break
145			}
146			cur = parent
147		}
148	
149		return active
150	}
