152	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
153		sessionRef := input.SessionRef
154		if sessionRef == "" {
155			return protocol.AgentSessionJSON{}, errors.New("session_ref is required")
156		}
157	
158		data, err := os.ReadFile(sessionRef)
159		if err != nil {
160			return protocol.AgentSessionJSON{}, fmt.Errorf("read session file: %w", err)
161		}
162	
163		sessionID := input.SessionID
164		if sessionID == "" {
165			sessionID = extractSessionIDFromPath(sessionRef)
166		}
167	
168		var startTime string
169		scanner := newJSONLScanner(data)
170		for scanner.Scan() {
171			var entry sessionEntry
172			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
173				continue
174			}
175			if entry.Type == "session" {
176				startTime = entry.Timestamp
177				if sessionID == "" {
178					sessionID = entry.ID
179				}
180				break
181			}
182		}
183	
184		return protocol.AgentSessionJSON{
185			SessionID:     sessionID,
186			AgentName:     "pi",
187			RepoPath:      protocol.RepoRoot(),
188			SessionRef:    sessionRef,
189			StartTime:     startTime,
190			NativeData:    data,
191			ModifiedFiles: []string{},
192			NewFiles:      []string{},
193			DeletedFiles:  []string{},
194		}, nil
195	}
