197	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
198		if session.SessionRef == "" {
199			return errors.New("session_ref is required")
200		}
201		if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
202			return err
203		}
204		return os.WriteFile(session.SessionRef, session.NativeData, 0o600)
205	}
