249	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
250		data, err := os.ReadFile(path)
251		if err != nil {
252			return nil, 0, err
253		}
254	
255		totalLines := countLines(data)
256		active := resolveActiveBranch(data)
257	
258		content := skipLines(data, offset)
259	
260		seen := make(map[string]bool)
261		var files []string
262	
263		scanner := newJSONLScanner(content)
264		for scanner.Scan() {
265			var entry messageEntry
266			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
267				continue
268			}
269			if entry.Type != entryTypeMessage {
270				continue
271			}
272			if active != nil && !active[entry.ID] {
273				continue
274			}
275			if entry.Message.Role != "assistant" {
276				continue
277			}
278	
279			var items []contentItem
280			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
281				continue
282			}
283	
284			for _, item := range items {
285				if item.Type != "toolCall" {
286					continue
287				}
288				if item.Name != "write" && item.Name != "edit" {
289					continue
290				}
291				var args struct {
292					Path string `json:"path"`
293				}
294				if err := json.Unmarshal(item.Arguments, &args); err != nil {
295					continue
296				}
297				if args.Path != "" && !seen[args.Path] {
298					seen[args.Path] = true
299					files = append(files, args.Path)
300				}
301			}
302		}
303	
304		return files, totalLines, nil
305	}
