206	func collectCompactToolResults(data []byte, active map[string]bool) (map[string]compactToolResultJSON, error) {
207		results := map[string]compactToolResultJSON{}
208		scanner := newJSONLScanner(data)
209		for scanner.Scan() {
210			var entry messageEntry
211			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
212				continue
213			}
